ruleToc.chapterList:
@js:
var path="@@.last_page@href";
var data=java.getString(path);
var page=data.match(/page=(\d+)/)[1];
var url=baseUrl.replace(/$/,"&page=1");
var list=[{text:"第1章",href:baseUrl}];
if(data&&page){
	for(var i=2;i<=page;i++){
		var title=`第${i}章`;
		var link=url.replace(/\d+$/,i);
		list.push({text:title,href:link});
		}
		list;
	}

ruleContent.nextContentUrl:
@js:
try{
	if(/netUrl/.test(baseUrl)){
  url1 = java.get('url');
 page = String(java.ajax(url1)).match(/\(第1\/(\d+)页\)/)[1];
 // java.log(page)
list=[];
if(page>=2){
for(var i=2;i<=page;i++){
href = String(url1).replace(/(\d+).html/,"$1_"+i+".html");
list.push(href);
}
}
list
}else{
	 java.getString("a:contains()@href")
	}
}catch(e){}

